shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae4d6;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #294057;
    --crimson: #8f2d23;
    --sage: #2e5a44;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.75;
  }

  /* Reading Progress Bar */
  .progress-bar-wrap {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: transparent;
    z-index: 1001;
  }
  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }
  .wsj-monogram {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }
  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }
  .section-tag {
    font-family: var(--font-sans);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.3rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Section */
  .hero {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }
  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 1.25rem;
  }
  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 2px;
    background: var(--accent);
  }
  .hero-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2.1rem, 4.5vw, 3.6rem);
    line-height: 1.18;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.2rem;
    max-width: 960px;
  }
  :host([lang="en"]) .hero-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.08;
  }
  .hero-dek {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.1rem, 2vw, 1.4rem);
    line-height: 1.6;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }
  :host([lang="en"]) .hero-dek {
    font-family: var(--font-body-en);
    font-style: italic;
  }
  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }
  .byline-name {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.05em;
    text-transform: uppercase;
  }

  /* Stakes Ledger Strip */
  .stakes-strip {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    border-bottom: 1px solid var(--line);
    background: linear-gradient(180deg, rgba(243, 239, 230, 0.5) 0%, rgba(250, 248, 244, 0) 100%);
  }
  .stakes-header {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--muted);
    margin-bottom: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .stakes-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
  }
  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--ink);
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  .metric-card.highlight-accent {
    border-top-color: var(--accent);
  }
  .metric-val {
    font-family: var(--font-mono);
    font-size: clamp(1.55rem, 2.5vw, 2.1rem);
    font-weight: 700;
    color: var(--ink);
    line-height: 1.15;
    margin-bottom: 0.45rem;
  }
  .metric-card.highlight-accent .metric-val {
    color: var(--accent);
  }
  .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--body);
    margin-bottom: 0.35rem;
  }
  .metric-note {
    font-family: var(--font-sans);
    font-size: 0.74rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Main Editorial Layout Container */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3rem 1.5rem;
  }

  /* Asymmetric 2-Column Rail */
  .chapter-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.5fr);
    gap: 3.5rem;
    align-items: start;
    margin-bottom: 3.5rem;
  }
  .prose-col {
    max-width: 680px;
  }
  .rail-col {
    position: sticky;
    top: 4.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    margin-bottom: 1.55rem;
    color: var(--body);
    text-align: left;
  }
  :host([lang="zh-CN"]) .prose-p {
    line-height: 1.92;
    letter-spacing: 0.01em;
  }
  :host([lang="en"]) .prose-p {
    font-size: 1.14rem;
    line-height: 1.78;
  }

  /* Lead Paragraph Styling (No ::first-letter on Chinese!) */
  .prose-lead {
    font-size: 1.26rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 4px solid var(--accent);
    padding-left: 1.25rem;
    margin-bottom: 1.85rem;
  }
  :host([lang="en"]) .prose-lead {
    font-size: 1.28rem;
  }

  /* Pivot Short Paragraph */
  .prose-pivot {
    font-size: 1.32rem;
    font-weight: 700;
    color: var(--crimson);
    background: var(--paper-card);
    border-left: 4px solid var(--crimson);
    padding: 1rem 1.35rem;
    margin: 2rem 0;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.18) 0%, rgba(184, 93, 25, 0.18) 100%);
    color: inherit;
    padding: 0.05em 0.25em;
    border-bottom: 1.5px solid var(--accent);
    font-weight: 600;
  }

  /* Chapter Headers */
  .chapter-banner {
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line);
    padding: 1.25rem 0;
    margin: 3.5rem 0 2.5rem;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: var(--accent);
  }
  .chapter-title {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.4rem, 2.5vw, 1.95rem);
    font-weight: 700;
    color: var(--ink);
    flex: 1;
  }
  :host([lang="en"]) .chapter-title {
    font-family: var(--font-serif-en);
  }
  .chapter-sub {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }

  /* Pull Quotes */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.6rem 1.5rem;
    position: relative;
  }
  .pull-quote::before {
    content: "“";
    font-family: var(--font-serif-en);
    font-size: 3.5rem;
    line-height: 1;
    color: var(--accent);
    opacity: 0.35;
    position: absolute;
    top: 0.5rem;
    left: 0.85rem;
  }
  .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.15rem;
    font-weight: 700;
    line-height: 1.6;
    color: var(--ink);
    position: relative;
    z-index: 1;
    margin-bottom: 0.85rem;
  }
  :host([lang="en"]) .quote-text {
    font-family: var(--font-serif-en);
    font-style: italic;
    font-size: 1.2rem;
  }
  .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--muted);
  }

  /* Dossier & Sidebar Cards */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
  }
  .dossier-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 0.5rem;
  }
  .dossier-title {
    font-family: var(--font-sans);
    font-size: 1rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 1rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid var(--line);
  }
  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }
  .dossier-item {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    line-height: 1.55;
    color: var(--body);
  }
  .dossier-item strong {
    color: var(--ink);
    display: block;
    font-size: 0.86rem;
    margin-bottom: 0.15rem;
  }

  /* Bespoke SVG Visual Exhibits */
  .exhibit-box {
    background: var(--navy-bg);
    color: #f4f1ea;
    border-radius: 4px;
    padding: 2rem 1.75rem;
    margin: 2.75rem 0;
    border: 1px solid var(--navy-line);
    box-shadow: 0 12px 30px rgba(15, 29, 43, 0.12);
  }
  .exhibit-box.light-exhibit {
    background: var(--paper-card);
    color: var(--ink);
    border: 1px solid var(--line-strong);
    box-shadow: none;
  }
  .exhibit-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1.25rem;
    padding-bottom: 0.9rem;
    border-bottom: 1px solid rgba(255,255,255,0.14);
  }
  .light-exhibit .exhibit-head {
    border-bottom-color: var(--line-strong);
  }
  .exhibit-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #e89954;
    display: block;
    margin-bottom: 0.3rem;
  }
  .light-exhibit .exhibit-tag {
    color: var(--accent);
  }
  .exhibit-title {
    font-family: var(--font-sans);
    font-size: 1.15rem;
    font-weight: 700;
    color: #ffffff;
  }
  .light-exhibit .exhibit-title {
    color: var(--ink);
  }
  .exhibit-sub {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: #b0becf;
    margin-top: 0.25rem;
  }
  .light-exhibit .exhibit-sub {
    color: var(--muted);
  }
  .exhibit-foot {
    margin-top: 1rem;
    padding-top: 0.75rem;
    border-top: 1px solid rgba(255,255,255,0.1);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: #8fa3b8;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }
  .light-exhibit .exhibit-foot {
    border-top-color: var(--line);
    color: var(--muted);
  }

  /* Verdict Climax Box */
  .verdict-box {
    background: var(--ink);
    color: var(--paper);
    padding: 2.5rem 2rem;
    margin-top: 2.5rem;
    border-left: 6px solid var(--accent);
  }
  .verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    color: #e89954;
    margin-bottom: 0.85rem;
  }
  .verdict-box .prose-p {
    color: var(--paper);
    font-size: 1.25rem;
    font-weight: 600;
    line-height: 1.75;
    margin-bottom: 0;
  }

  /* Footer */
  .editorial-footer {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
  }

  /* Responsive Design */
  @media (max-width: 960px) {
    .stakes-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .chapter-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .rail-col {
      position: static;
    }
    .prose-col {
      max-width: 100%;
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .stakes-strip,
    .editorial-container,
    .editorial-footer {
      padding-left: 1rem;
      padding-right: 1rem;
    }
    .stakes-grid {
      grid-template-columns: 1fr;
    }
    .exhibit-box {
      padding: 1.35rem 1rem;
    }
    .verdict-box {
      padding: 1.75rem 1.25rem;
    }
  }
